// Detecta emojis de verdad: los de presentación gráfica, los que llevan el selector FE0F y los números con recuadro.
// Los símbolos de los palos (♠ ♥ ♦ ♣) y los signos ✓ ✕ ★ → ← se dejan como texto.
const REGEX_EMOJI = /(?:[0-9#*]️?⃣)|(?:\p{Extended_Pictographic}(?:️|\p{Emoji_Modifier})?(?:‍\p{Extended_Pictographic}️?)*)/gu;
const esEmojiReal = (m) => /️|⃣|‍/.test(m) || /^\p{Emoji_Presentation}/u.test(m);

function nombreDeIcono(emoji) {
  const base = emoji.replace(/[️‍]/g, '');
  if (/⃣/.test(emoji)) return /^1/.test(emoji) ? 'estrella' : /^3/.test(emoji) ? 'numeros' : 'numeros';
  const primero = Array.from(base)[0];
  return EMOJI_A_ICONO[primero] || 'estrella';
}

function icono(nombre, clase = '') {
  const nodo = document.createElement('span');
  nodo.className = ('ico ico-' + nombre + ' ' + clase).trim();
  nodo.setAttribute('role', 'img');
  nodo.setAttribute('aria-label', NOMBRE_ICONO[nombre] || nombre);
  nodo.dataset.icono = nombre;
  nodo.innerHTML = ICONOS[nombre] || ICONOS.estrella;
  return nodo;
}
// Quita los emojis de un texto (para atributos como aria-label o title)
const sinEmojis = (t) => String(t).replace(REGEX_EMOJI, (m) => (esEmojiReal(m) ? '' : m)).replace(/\s{2,}/g, ' ').trim();

// Cambia los emojis de los textos de un nodo por iconos
function sustituirEmojis(raiz) {
  if (!raiz) return;
  const pendientes = [];
  const caminante = document.createTreeWalker(raiz, NodeFilter.SHOW_TEXT, {
    acceptNode: (n) => {
      const p = n.parentNode;
      if (!p || /^(SCRIPT|STYLE|TEXTAREA|TITLE)$/.test(p.nodeName)) return NodeFilter.FILTER_REJECT;
      REGEX_EMOJI.lastIndex = 0;
      return REGEX_EMOJI.test(n.nodeValue) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT;
    },
  });
  while (caminante.nextNode()) pendientes.push(caminante.currentNode);
  for (const t of pendientes) {
    const texto = t.nodeValue;
    const trozos = [];
    let ultimo = 0, hay = false;
    REGEX_EMOJI.lastIndex = 0;
    let m;
    while ((m = REGEX_EMOJI.exec(texto))) {
      if (!esEmojiReal(m[0])) continue;
      hay = true;
      if (m.index > ultimo) trozos.push(document.createTextNode(texto.slice(ultimo, m.index)));
      trozos.push(icono(nombreDeIcono(m[0])));
      ultimo = m.index + m[0].length;
    }
    if (!hay) continue;
    if (ultimo < texto.length) trozos.push(document.createTextNode(texto.slice(ultimo)));
    t.replaceWith(...trozos);
  }
}

// Hoja de degradados + observador (se activa en cuanto existe el cuerpo de la página)
function iniciarIconos() {
  const caja = document.createElement('div');
  caja.innerHTML = SPRITE;
  document.body.prepend(caja.firstChild);
  sustituirEmojis(document.body);
  new MutationObserver((cambios) => {
    for (const c of cambios) {
      if (c.type === 'characterData') sustituirEmojis(c.target.parentNode);
      else c.addedNodes.forEach((n) => (n.nodeType === 1 ? sustituirEmojis(n) : n.nodeType === 3 && n.parentNode ? sustituirEmojis(n.parentNode) : null));
    }
  }).observe(document.body, { childList: true, characterData: true, subtree: true });
}
if (document.body) iniciarIconos(); else document.addEventListener('DOMContentLoaded', iniciarIconos);
